function texto(valor) {
  return String(valor ?? '').trim();
}

function removerDecimaisZero(valor) {
  return valor.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function escaparOData(valor) {
  return texto(valor).replace(/'/g, "''");
}

function aplicarMapaPorPalavra(valor, mapa) {
  let resultado = valor;

  const termos = Object.keys(mapa)
    .sort((a, b) => b.length - a.length);

  for (const termo of termos) {
    const substituto = mapa[termo];

    const termoEscapado = termo.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

    resultado = resultado.replace(
      new RegExp(`\\b${termoEscapado}\\b`, 'g'),
      substituto
    );
  }

  return resultado;
}

function removerPalavras(valor, palavras) {
  let resultado = valor;

  for (const palavra of palavras) {
    resultado = resultado.replace(
      new RegExp(`\\b${palavra}\\b`, 'g'),
      ' '
    );
  }

  return resultado;
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

/* -------------------------------------------------------------------------- */
/* DicionÃ¡rios                                                                */
/* -------------------------------------------------------------------------- */

const sinonimosGlobais = {
  PÃ‡: 'UN',
  PC: 'UN',
  PCA: 'UN',
  PECA: 'UN',
  UND: 'UN',
  UNID: 'UN',
  UNIDADE: 'UN',

  METRO: 'M',
  METROS: 'M',

  QTD: 'QUANTIDADE',

  ELETR: 'ELETRICO',
  ELET: 'ELETRICO',

  TRIF: 'TRIFASICO',
  MONOF: 'MONOFASICO',

  EXT: 'EXTERNO',
  INT: 'INTERNO'
};

const sinonimosPorFamilia = {
  CABOS: {
    CU: 'COBRE',
    COB: 'COBRE',
    AL: 'ALUMINIO',
    ALUM: 'ALUMINIO',

    FLEX: 'FLEXIVEL',
    FLEXIV: 'FLEXIVEL',

    RIG: 'RIGIDO',

    COND: 'CONDUTOR',

    XLPE: 'XLPE',
    EPR: 'EPR',
    PVC: 'PVC'
  },

  DISJUNTORES: {
    DISJ: 'DISJUNTOR',
    DJ: 'DISJUNTOR',

    MONOP: 'MONOPOLAR',
    UNIP: 'MONOPOLAR',
    UNIPOLAR: 'MONOPOLAR',

    BIP: 'BIPOLAR',
    '2P': 'BIPOLAR',

    TRIP: 'TRIPOLAR',
    '3P': 'TRIPOLAR',

    TETRAP: 'TETRAPOLAR',
    '4P': 'TETRAPOLAR',

    CM: 'CAIXA MOLDADA',
    MCCB: 'CAIXA MOLDADA',
    MCB: 'MINIDISJUNTOR'
  },

  ELETRODUTOS: {
    ELETROD: 'ELETRODUTO',
    ELETRODUTO: 'ELETRODUTO',

    CORR: 'CORRUGADO',

    GALV: 'GALVANIZADO',

    PEAD: 'PEAD',
    PVC: 'PVC'
  },

  POSTES: {
    CONC: 'CONCRETO',

    DT: 'DUPLO T',
    DUPLOT: 'DUPLO T',

    CIRC: 'CIRCULAR'
  },

  TRANSFORMADORES: {
    TRAFO: 'TRANSFORMADOR',
    TRANSF: 'TRANSFORMADOR',

    OLEO: 'OLEO',
    SECO: 'SECO'
  },

  CONECTORES: {
    CONECT: 'CONECTOR',
    CONEC: 'CONECTOR',

    PERF: 'PERFURANTE',

    COMP: 'COMPRESSAO'
  },

  TERMINAIS: {
    TERM: 'TERMINAL',

    COMP: 'COMPRESSAO'
  },

  ISOLADORES: {
    ISOL: 'ISOLADOR',

    POLIM: 'POLIMERICO',

    PORC: 'PORCELANA'
  },

  BARRAMENTOS: {
    BARR: 'BARRAMENTO',

    CU: 'COBRE',
    AL: 'ALUMINIO'
  }
};

/*
 * Removemos apenas palavras de ligaÃ§Ã£o.
 * NÃ£o remover â€œTIPOâ€, â€œCLASSEâ€, â€œCURVAâ€, â€œEXTERNOâ€ ou â€œINTERNOâ€,
 * pois podem diferenciar materiais.
 */
const palavrasLigacao = [
  'DE',
  'DA',
  'DO',
  'DAS',
  'DOS',
  'EM',
  'PARA'
];

/* -------------------------------------------------------------------------- */
/* IdentificaÃ§Ã£o de famÃ­lia                                                   */
/* -------------------------------------------------------------------------- */

function identificarFamilia(valor) {
  const descricao = limparEspacos(valor);

  if (
    /\bTC\b/.test(descricao) ||
    /\bTP\b/.test(descricao) ||
    /\bTRANSFORMADOR DE CORRENTE\b/.test(descricao) ||
    /\bTRANSFORMADOR DE POTENCIAL\b/.test(descricao)
  ) {
    return 'TRANSFORMADORES_MEDICAO';
  }

  if (
    /\bPARA[\s-]*RAIOS?\b/.test(descricao) ||
    /\bPARARRAIOS?\b/.test(descricao)
  ) {
    return 'PROTECAO_ELETRICA';
  }

  if (
    /\bCABO\b/.test(descricao) ||
    /\bCONDUTOR\b/.test(descricao)
  ) {
    return 'CABOS';
  }

  if (
    /\bDISJUNTOR\b/.test(descricao) ||
    /\bDISJ\b/.test(descricao) ||
    /\bMCCB\b/.test(descricao) ||
    /\bMCB\b/.test(descricao)
  ) {
    return 'DISJUNTORES';
  }

  if (
    /\bELETRODUTO\b/.test(descricao) ||
    /\bELETROD\b/.test(descricao)
  ) {
    return 'ELETRODUTOS';
  }

  if (/\bPOSTE\b/.test(descricao)) {
    return 'POSTES';
  }

  if (
    /\bTRANSFORMADOR\b/.test(descricao) ||
    /\bTRAFO\b/.test(descricao) ||
    /\bTRANSF\b/.test(descricao)
  ) {
    return 'TRANSFORMADORES';
  }

  if (
    /\bCONECTOR\b|\bCONECT\b|\bCONEC\b/.test(descricao)
  ) {
    return 'CONECTORES';
  }

  if (
    /\bTERMINAL\b|\bTERM\b/.test(descricao)
  ) {
    return 'TERMINAIS';
  }

  if (
    /\bISOLADOR\b|\bISOL\b/.test(descricao)
  ) {
    return 'ISOLADORES';
  }

  if (
    /\bBARRAMENTO\b|\bBARR\b/.test(descricao)
  ) {
    return 'BARRAMENTOS';
  }

  if (
    /\bCHAVE SECCIONADORA\b/.test(descricao) ||
    /\bSECCIONADORA\b/.test(descricao)
  ) {
    return 'CHAVES_SECCIONADORAS';
  }

  if (
    /\bCAIXA PASSAGEM\b/.test(descricao) ||
    /\bCAIXA DE PASSAGEM\b/.test(descricao)
  ) {
    return 'CAIXAS_PASSAGEM';
  }

  return 'OUTROS';
}

function mapearFamiliaSharePoint(familia) {
  const mapa = {
    CABOS: 'CABOS_E_CONDUTORES',
    CONECTORES: 'CONEXOES_E_TERMINAIS',
    TERMINAIS: 'CONEXOES_E_TERMINAIS',
    POSTES: 'ESTRUTURAS_E_FERRAGENS',
    PROTECAO_ELETRICA: 'PROTECAO_ELETRICA',
    TRANSFORMADORES_MEDICAO: 'TRANSFORMADORES_MEDICAO',
    OUTROS: 'OUTROS',
    DISJUNTORES: 'OUTROS',
    ELETRODUTOS: 'OUTROS',
    TRANSFORMADORES: 'OUTROS',
    ISOLADORES: 'OUTROS',
    BARRAMENTOS: 'OUTROS',
    CHAVES_SECCIONADORAS: 'OUTROS',
    CAIXAS_PASSAGEM: 'OUTROS'
  };

  return mapa[familia] || 'OUTROS';
}

/* -------------------------------------------------------------------------- */
/* PadronizaÃ§Ã£o tÃ©cnica                                                       */
/* -------------------------------------------------------------------------- */

function padronizarUnidades(valor) {
  let resultado = valor;

  // SeÃ§Ã£o de condutor
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\s*[Â²2]\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MM2\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MMQ\b/g, '$1 MM2');

  // DiÃ¢metro e dimensÃµes lineares
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\b/g, '$1 MM')
    .replace(/(\d+(?:[.,]\d+)?)\s*CM\b/g, '$1 CM')
    .replace(/(\d+(?:[.,]\d+)?)\s*M\b/g, '$1 M');

  // Corrente
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*AMPERES?\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*AMP\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*A\b/g, '$1 A');

  // TensÃ£o
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KV\b/g, '$1 KV')
    .replace(/(\d+(?:[.,]\d+)?)\s*V\b/g, '$1 V');

  // PotÃªncia ativa, aparente e reativa
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KVAR\b/g, '$1 KVAR')
    .replace(/(\d+(?:[.,]\d+)?)\s*KVA\b/g, '$1 KVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*MVA\b/g, '$1 MVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*KW\b/g, '$1 KW')
    .replace(/(\d+(?:[.,]\d+)?)\s*MW\b/g, '$1 MW');

  // ForÃ§a / carga mecÃ¢nica
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*DAN\b/g, '$1 DAN');

  // Capacidade de interrupÃ§Ã£o
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KA\b/g, '$1 KA');

  // PotÃªncia mecÃ¢nica
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*CV\b/g, '$1 CV')
    .replace(/(\d+(?:[.,]\d+)?)\s*HP\b/g, '$1 HP');

  return resultado;
}

function padronizarNumeros(valor) {
  return valor.replace(
    /(\d),(\d)/g,
    '$1.$2'
  );
}

function padronizarTensoesDeCabo(valor, familia) {
  if (familia !== 'CABOS') {
    return valor;
  }

  let resultado = valor;

  resultado = resultado
    .replace(
      /\b0[.,]6\s*[\/\\-]\s*1\s*KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b0\s+6\s+1\s+KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b600\s*[\/\\-]\s*1000\s*V\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b450\s*[\/\\-]\s*750\s*V\b/g,
      '450/750 V'
    );

  return resultado;
}

function padronizarPolos(valor, familia) {
  if (familia !== 'DISJUNTORES') {
    return valor;
  }

  return valor
    .replace(/\b1\s*P\b/g, 'MONOPOLAR')
    .replace(/\b2\s*P\b/g, 'BIPOLAR')
    .replace(/\b3\s*P\b/g, 'TRIPOLAR')
    .replace(/\b4\s*P\b/g, 'TETRAPOLAR');
}

function padronizarDimensoes(valor) {
  return valor
    .replace(
      /(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 MM'
    )
    .replace(
      /(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 X $3 MM'
    );
}

/* -------------------------------------------------------------------------- */
/* GeraÃ§Ã£o das chaves                                                         */
/* -------------------------------------------------------------------------- */

function normalizarDescricao(valor) {
  let resultado = removerAcentos(valor)
    .toUpperCase()
    .replace(/Â²/g, '2')
    .replace(/[â€œâ€"'`Â´]/g, ' ')
    .replace(/[(){}\[\]]/g, ' ')
    .replace(/[;:]/g, ' ')
    .replace(/â€“|â€”/g, '-');

  resultado = limparEspacos(resultado);

  const familia = identificarFamilia(resultado);

  resultado = aplicarMapaPorPalavra(
    resultado,
    sinonimosGlobais
  );

  const regrasFamilia =
    sinonimosPorFamilia[familia] || {};

  resultado = aplicarMapaPorPalavra(
    resultado,
    regrasFamilia
  );

  resultado = padronizarNumeros(resultado);
  resultado = padronizarUnidades(resultado);
  resultado = removerDecimaisZero(resultado);

  resultado = padronizarTensoesDeCabo(
    resultado,
    familia
  );

  resultado = padronizarPolos(
    resultado,
    familia
  );

  resultado = padronizarDimensoes(resultado);

  /*
   * Preserva "/" em tensÃµes como 0.6/1 KV e cÃ³digos como 12/600.
   * Preserva "." para valores decimais.
   */
  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

const palavrasRemover =
  familia === 'PROTECAO_ELETRICA' &&
  /\bPARA[\s-]*RAIOS?\b/.test(
    removerAcentos(valor).toUpperCase()
  )
    ? palavrasLigacao.filter(p => p !== 'PARA')
    : palavrasLigacao;

resultado = removerPalavras(
  resultado,
  palavrasRemover
);

  resultado = limparEspacos(resultado);

  return {
    descricao_normalizada: resultado,
    familia
  };
}

function normalizarCodigo(valor) {
  const codigo = String(valor ?? '').trim();

  if (
    !codigo ||
    codigo === '0' ||
    codigo.toLowerCase() === 'null' ||
    codigo.toLowerCase() === 'undefined'
  ) {
    return '';
  }

  return codigo;
}

function mapearOrigemCatalogo(valor) {
  const origem = String(valor ?? '')
    .trim()
    .toUpperCase();

  const mapa = {
    'NEOENERGIA_SUBESTACOES': 'SUBESTACAO_NEOENERGIA',
    'SUBESTACAO_NEOENERGIA': 'SUBESTACAO_NEOENERGIA',

    'NEOENERGIA_REDE': 'REDE_NEOENERGIA',
    'REDE_NEOENERGIA': 'REDE_NEOENERGIA',

    '3P': '3P',
    'AMBOS': 'AMBOS'
  };

  return mapa[origem] || '';
}

/* -------------------------------------------------------------------------- */
/* Processamento                                                              */
/* -------------------------------------------------------------------------- */

return $input.all().map((item, index) => {
  const row = item.json || {};

  /* ------------------------------------------------------------------------ */
  /* CÃ³digos externos                                                         */
  /* ------------------------------------------------------------------------ */

  const codigoNeoenergia =
    normalizarCodigo(row.codigo_neoenergia);

  const codigoElektro =
    normalizarCodigo(row.codigo_elektro);

  const codigoBrasilia =
    normalizarCodigo(row.codigo_brasilia);

  const possuiCodigoIdentidade = Boolean(
    codigoNeoenergia ||
    codigoElektro ||
    codigoBrasilia
  );

  const quantidadeCodigosIdentidade = [
    codigoNeoenergia,
    codigoElektro,
    codigoBrasilia
  ].filter(Boolean).length;

  /* ------------------------------------------------------------------------ */
  /* DescriÃ§Ã£o e normalizaÃ§Ã£o                                                 */
  /* ------------------------------------------------------------------------ */

  const descricao = texto(
    row.descricao ||
    row.Material ||
    row.Title
  );

const origemCatalogo =
  mapearOrigemCatalogo(row.fonte);

  const normalizado = descricao
    ? normalizarDescricao(descricao)
    : {
        descricao_normalizada: '',
        familia: 'OUTROS'
      };

  const nomeNormalizado =
    texto(row.nome_normalizado) ||
    normalizado.descricao_normalizada;

  const familiaSharePoint =
    mapearFamiliaSharePoint(normalizado.familia);

  /* ------------------------------------------------------------------------ */
  /* Fallback para material sem cÃ³digo                                        */
  /* ------------------------------------------------------------------------ */

 const chaveFallback = [
  nomeNormalizado,
  familiaSharePoint,
  texto(row.subfamilia),
  texto(row.especificacao_tecnica)
]
    .map(v =>
