        .toUpperCase()
        .trim()
    )
    .filter(Boolean)
    .join('|');

  const possuiIdentidade = Boolean(
    possuiCodigoIdentidade ||
    chaveFallback
  );

  /* ------------------------------------------------------------------------ */
  /* Filtro OData                                                             */
  /* ------------------------------------------------------------------------ */

  const filtrosIdentidade = [];

  if (codigoNeoenergia) {
    filtrosIdentidade.push(
      `fields/Codigo_Neoenergia eq '${escaparOData(codigoNeoenergia)}'`
    );
  }

  if (codigoElektro) {
    filtrosIdentidade.push(
      `fields/Codigo_Elektro eq '${escaparOData(codigoElektro)}'`
    );
  }

  if (codigoBrasilia) {
    filtrosIdentidade.push(
      `fields/Codigo_Brasilia eq '${escaparOData(codigoBrasilia)}'`
    );
  }

 let filtroIdentidadeOData = '';

if (filtrosIdentidade.length > 0) {
  filtroIdentidadeOData =
    filtrosIdentidade.join(' or ');
} else {
  const filtrosFallback = [];

  if (nomeNormalizado) {
    filtrosFallback.push(
      `fields/Nome_Normalizado eq '${escaparOData(nomeNormalizado)}'`
    );
  }

  if (texto(row.subfamilia)) {
    filtrosFallback.push(
      `fields/Subfamilia eq '${escaparOData(texto(row.subfamilia))}'`
    );
  }

  filtroIdentidadeOData =
    filtrosFallback.join(' and ');
}

  /* ------------------------------------------------------------------------ */
  /* CenÃ¡rio de identidade                                                    */
  /* ------------------------------------------------------------------------ */

  const cenarioIdentidade =
    [
      codigoNeoenergia ? 'NE' : null,
      codigoElektro ? 'EL' : null,
      codigoBrasilia ? 'BR' : null
    ]
      .filter(Boolean)
      .join('+') || 'SEM_CODIGO';

  /* ------------------------------------------------------------------------ */
  /* SaÃ­da                                                                    */
  /* ------------------------------------------------------------------------ */

  return {
    json: {
      ...row,

      catalogo_item_id:
        row.catalogo_item_id
          ? Number(row.catalogo_item_id)
