      descricao,

      nome_normalizado: nomeNormalizado,

      familia: familiaSharePoint,

categoria:
  familiaSharePoint === 'PROTECAO_ELETRICA' &&
  /\bPARA[\s-]*RAIOS?\b/.test(
    removerAcentos(descricao).toUpperCase()
  )
    ? 'PARA_RAIOS'
    : texto(row.categoria),

      especificacao_tecnica:
        texto(row.especificacao_tecnica),

      fonte:
        texto(row.fonte),

      origem_catalogo:
  origemCatalogo,

      /* CÃ³digos */
      codigo_neoenergia: codigoNeoenergia,
      codigo_neoenergia_odata:
        escaparOData(codigoNeoenergia),

      codigo_elektro: codigoElektro,
      codigo_elektro_odata:
        escaparOData(codigoElektro),

      codigo_brasilia: codigoBrasilia,
