      possui_identidade:
        possuiIdentidade,

      filtro_identidade_odata:
        filtroIdentidadeOData,

      revisao_material_oficial:
        possuiIdentidade
          ? null
          : 'SEM_IDENTIDADE'
    },

    pairedItem: {
      item: item.pairedItem?.item ?? index
    }
  };
});

const entrada = $('PREP - Identidade Material Oficial').item.json;

const encontrados = Array.isArray($json.value)
  ? $json.value
  : [];

const idsUnicos = [
  ...new Set(
    encontrados
      .map(item => Number(item.id))
      .filter(Boolean)
  )
];

if (idsUnicos.length === 0) {
  throw new Error(
    `Nenhum Material Oficial encontrado para a identidade: ${entrada.cenario_identidade}`
  );
}

if (idsUnicos.length > 1) {
  throw new Error(
    `CONFLITO DE IDENTIDADE: busca retornou Materiais Oficiais distintos: ${idsUnicos.join(', ')}`
  );
}

const materialEncontrado = encontrados.find(
  item => Number(item.id) === idsUnicos[0]
);

const existente = materialEncontrado?.fields || {};

function normalizar(valor) {
  const v = String(valor ?? '').trim();

  if (
    !v ||
    v === '0' ||
    v.toLowerCase() === 'null' ||
    v.toLowerCase() === 'undefined'
  ) {
    return '';
  }

  return v;
}

function resolverCodigo(nome, valorEntrada, valorExistente) {
  const recebido = normalizar(valorEntrada);
  const atual = normalizar(valorExistente);

  if (atual && recebido && atual !== recebido) {
    throw new Error(
      `CONFLITO ${nome}: existente=${atual}, recebido=${recebido}, Material Oficial=${idsUnicos[0]}`
    );
  }

  return atual || recebido || '';
}

const codigoNeoenergiaFinal = resolverCodigo(
  'Codigo_Neoenergia',
  entrada.codigo_neoenergia,
  existente.Codigo_Neoenergia
);

const codigoElektroFinal = resolverCodigo(
  'Codigo_Elektro',
  entrada.codigo_elektro,
  existente.Codigo_Elektro
);

const codigoBrasiliaFinal = resolverCodigo(
  'Codigo_Brasilia',
  entrada.codigo_brasilia,
  existente.Codigo_Brasilia
);

const identidadeEncontradaPor =
  entrada.possui_codigo_identidade
    ? entrada.cenario_identidade
    : 'FALLBACK_NOME_SUBFAMILIA';

return {
  json: {
    ...entrada,

    material_oficial_id: idsUnicos[0],
    material_oficial_origem: 'EXISTENTE',

    codigo_neoenergia_final: codigoNeoenergiaFinal,
    codigo_elektro_final: codigoElektroFinal,
    codigo_brasilia_final: codigoBrasiliaFinal,

    identidade_encontrada_por: identidadeEncontradaPor,

    quantidade_matches_identidade: encontrados.length,

    fallback_utilizado:
      !entrada.possui_codigo_identidade
  }
};

const entrada = $('PREP - Identidade Material Oficial').item.json;
const id = Number($json.id);
if (!id) throw new Error(`POST nÃ£o retornou ID para o SAP ${entrada.codigo_neoenergia}`);
return { json: { ...entrada, material_oficial_id: id, material_oficial_origem: 'CRIADO' } };
